var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
return new{scene=scene.path,scene.isDirty,playing=UnityEditor.EditorApplication.isPlaying,activeTarget=UnityEditor.EditorUserBuildSettings.activeBuildTarget.ToString(),architectures=UnityEditor.PlayerSettings.Android.targetArchitectures.ToString(),backend=UnityEditor.PlayerSettings.GetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android).ToString(),customKeystore=UnityEditor.PlayerSettings.Android.useCustomKeystore,androidModule=UnityEditor.BuildPipeline.IsBuildTargetSupported(UnityEditor.BuildTargetGroup.Android,UnityEditor.BuildTarget.Android),scenes=UnityEditor.EditorBuildSettings.scenes.Where(s=>s.enabled).Select(s=>s.path).ToArray()};
